<span class="line"><span style="color:#D73A49;">for</span><span style="color:#24292E;"> combo </span><span style="color:#D73A49;">in</span><span style="color:#24292E;"> itertools.product([</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">2</span><span style="color:#24292E;">], [</span><span style="color:#032F62;">&quot;a&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;b&quot;</span><span style="color:#24292E;">]):</span></span>
